def _ndarray_to_jsonable(value):
    """Convert a numpy array or numpy scalar into a JSON-serializable representation.

    The dtype and shape are preserved so the exact array (including 0-d scalar arrays) can be
    faithfully reconstructed by :func:`_jsonable_to_ndarray`.
    """
    array = np.asarray(value)
    return {
        "__ndarray__": array.tolist(),
        "dtype": str(array.dtype),
        "shape": list(array.shape),
    }


def _jsonable_to_ndarray(value):
    """Reconstruct a numpy array (including 0-d scalar arrays) from its JSON representation."""
    array = np.array(value["__ndarray__"], dtype=np.dtype(value["dtype"]))
    return array.reshape(tuple(value["shape"]))


def save_tensors_data(tensors_data: TensorsData, path: str | Path, smooth_quant: bool = False) -> None:
    """Serialize a :class:`TensorsData` object to a JSON file.

    Missing parent directories are created automatically. The output JSON contains a top-level
    ``smooth_quant`` boolean field. Scalar numpy values (e.g. ``np.int64`` bins) are serialized as
    plain integers.
