    if path.parent and not path.parent.exists():
        path.parent.mkdir(parents=True, exist_ok=True)

    serialized_data = {}
    for name, tensor_data in tensors_data.data.items():
        attrs = {}
        for attr in tensor_data._attrs:
            v = getattr(tensor_data, attr)
            if isinstance(v, (np.ndarray, np.generic)):
                attrs[attr] = _ndarray_to_jsonable(v)
            elif attr == "bins":
                attrs[attr] = int(v)
            else:
                attrs[attr] = v
        serialized_data[name] = attrs

